<script setup lang="ts">
import { onMounted, ref } from "vue";import { BadgeCheck, Building2, CreditCard, Handshake, ReceiptText, Users } from "lucide-vue-next";import PageHeader from "../components/PageHeader.vue";import { http, apiMessage } from "../api/http";
interface Overview{plans:number;activeSubscriptions:number;verifiedProviders:number;activeProducts:number;orders:number;pendingRefunds:number;activeSponsors:number;payment:{available:boolean;provider:string;message:string}}
const data=ref<Overview|null>(null);const error=ref("");onMounted(async()=>{try{data.value=(await http.get("/commercial/overview")).data.data;}catch(e){error.value=apiMessage(e);}});
const metrics=[['plans','机构方案',Building2],['activeSubscriptions','有效授权',Users],['verifiedProviders','已核验服务商',BadgeCheck],['activeProducts','在售服务',Handshake],['orders','服务订单',ReceiptText],['pendingRefunds','待处理退款',CreditCard],['activeSponsors','展示中的合作位',Handshake]] as const;
</script>
<template><main><PageHeader title="商业运营" description="机构授权、可信服务和订单状态；合作内容与官方内容严格分开。"/><p v-if="error" class="inline-error">{{error}}</p><section v-if="data" class="panel commercial-metrics"><article v-for="item in metrics" :key="item[0]"><component :is="item[2]"/><small>{{item[1]}}</small><strong>{{data[item[0]]}}</strong></article></section><section v-if="data" class="panel payment-boundary"><CreditCard/><div><h2>支付能力</h2><p>{{data.payment.message}}</p><b>{{data.payment.available?'支付 Provider 已配置':'REAL_PAYMENT_PROVIDER_ACCEPTANCE = BLOCKED_BY_CREDENTIALS'}}</b></div></section><section class="panel commercial-note"><h2>运营边界</h2><ul><li>机构方案价格和权益由平台配置，不写死“市场价”。</li><li>服务商必须核验后才能展示，且按地区限制服务范围。</li><li>赞助、合作服务和政府公开信息使用不同标签与展示位置。</li><li>没有真实商户凭据时只允许创建待支付订单，不产生支付成功事件。</li></ul></section></main></template>
